// ── 1. The Component Interface (implicit via duck typing in JS) ──
// Both ConcreteComponent and all decorators implement:
//   getCost() -> number
//   getDescription() -> string

// ── 2. Concrete Component ────────────────────────────────────────
class Espresso {
  getCost()        { return 2.00; }
  getDescription() { return 'Espresso'; }
}

// ── 3. Base Decorator ────────────────────────────────────────────
class CoffeeDecorator {
  constructor(coffee) {
    this._coffee = coffee;  // the wrappee — could be component OR another decorator
  }
  getCost()        { return this._coffee.getCost(); }         // pure delegation
  getDescription() { return this._coffee.getDescription(); }  // pure delegation
}

// ── 4. Concrete Decorators — each adds ONE behaviour ────────────
class MilkDecorator extends CoffeeDecorator {
  getCost()        { return super.getCost() + 0.50; }
  getDescription() { return super.getDescription() + ', Milk'; }
}

class CaramelDecorator extends CoffeeDecorator {
  getCost()        { return super.getCost() + 0.75; }
  getDescription() { return super.getDescription() + ', Caramel'; }
}

class WhipDecorator extends CoffeeDecorator {
  getCost()        { return super.getCost() + 0.60; }
  getDescription() { return super.getDescription() + ', Whip'; }
}

// ── 5. Client — assembles stacks at runtime ──────────────────────
const plain   = new Espresso();
console.log(plain.getDescription(), plain.getCost());  // Espresso 2

const withMilk = new MilkDecorator(new Espresso());
console.log(withMilk.getDescription(), withMilk.getCost()); // Espresso, Milk 2.5

// Stack all three on one espresso:
let deluxe = new Espresso();
deluxe = new MilkDecorator(deluxe);
deluxe = new CaramelDecorator(deluxe);
deluxe = new WhipDecorator(deluxe);

console.log(deluxe.getDescription()); // Espresso, Milk, Caramel, Whip
console.log(`$${deluxe.getCost().toFixed(2)}`); // $3.85

// Different order — Caramel before Milk:
const reordered = new WhipDecorator(
  new MilkDecorator(
    new CaramelDecorator(
      new Espresso()
    )
  )
);
console.log(reordered.getDescription()); // Espresso, Caramel, Milk, Whip
console.log(`$${reordered.getCost().toFixed(2)}`); // $3.85 — same cost, different description order

// ── Service decorators: logging, caching, auth ───────────────────

class UserService {
  getUser(id) {
    // In a real system: db.query('SELECT * FROM users WHERE id = ?', [id])
    return { id, name: 'Alice', role: 'admin', email: 'alice@example.com' };
  }
  updateUser(id, data) {
    return { id, ...data, updatedAt: new Date().toISOString() };
  }
}

// ── Logging Decorator ─────────────────────────────────────────────
class LoggingDecorator {
  constructor(service) { this._service = service; }

  getUser(id) {
    console.log(`[LOG ${new Date().toISOString()}] getUser(${id})`);
    const result = this._service.getUser(id);
    console.log(`[LOG] getUser → ${JSON.stringify(result)}`);
    return result;
  }

  updateUser(id, data) {
    console.log(`[LOG] updateUser(${id}, ${JSON.stringify(data)})`);
    const result = this._service.updateUser(id, data);
    console.log(`[LOG] updateUser → success`);
    return result;
  }
}

// ── Caching Decorator — memoises read operations only ─────────────
class CachingDecorator {
  constructor(service, ttlMs = 60_000) {
    this._service = service;
    this._cache   = new Map();
    this._ttlMs   = ttlMs;
  }

  getUser(id) {
    const cacheKey = `user:${id}`;
    const cached   = this._cache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < this._ttlMs) {
      console.log(`[CACHE] Hit: ${cacheKey}`);
      return cached.value;
    }
    const result = this._service.getUser(id);  // delegate
    this._cache.set(cacheKey, { value: result, timestamp: Date.now() });
    console.log(`[CACHE] Stored: ${cacheKey}`);
    return result;
  }

  updateUser(id, data) {
    // Write-through: invalidate cache on update
    this._cache.delete(`user:${id}`);
    console.log(`[CACHE] Invalidated: user:${id}`);
    return this._service.updateUser(id, data);  // delegate
  }
}

// ── Auth Decorator — guards before any delegation ─────────────────
class AuthDecorator {
  constructor(service, currentUserRole) {
    this._service         = service;
    this._currentUserRole = currentUserRole;
  }

  getUser(id) {
    // Anyone can read user data
    return this._service.getUser(id);
  }

  updateUser(id, data) {
    if (this._currentUserRole !== 'admin') {
      throw new Error('Unauthorised: admin role required to update users');
    }
    return this._service.updateUser(id, data);
  }
}

// ── Wiring: stack decorators at application startup ───────────────
const userSvc = new AuthDecorator(
  new CachingDecorator(
    new LoggingDecorator(
      new UserService()
    ),
    30_000  // 30 second TTL
  ),
  'admin'  // current user's role
);

// First call — cache miss, full chain executes
const u1 = userSvc.getUser(42);
// [LOG] getUser(42)
// [LOG] getUser → {id:42, name:'Alice', role:'admin', ...}
// [CACHE] Stored: user:42

// Second call — cache hit, log layer is NOT called (it's inside cache layer)
const u2 = userSvc.getUser(42);
// [CACHE] Hit: user:42

// Update — invalidates cache, auth passes
userSvc.updateUser(42, { name: 'Alice Smith' });
// [LOG] updateUser(42, {name:'Alice Smith'})
// [CACHE] Invalidated: user:42
// [LOG] updateUser → success

// ── TypeScript-style Decorator with interface enforcement ─────────
// (Illustrating the pattern; TS decorators are a separate concept)

// Component Interface — narrow, only two methods
class DataSource {
  write(data) { throw new Error('abstract'); }
  read()      { throw new Error('abstract'); }
}

// Concrete Component
class FileDataSource extends DataSource {
  constructor(filename) {
    super();
    this._filename = filename;
    this._data     = null;
  }
  write(data) {
    console.log(`[FILE] Writing to ${this._filename}:`, data);
    this._data = data;  // simulated file I/O
  }
  read() {
    console.log(`[FILE] Reading from ${this._filename}`);
    return this._data;
  }
}

// Base Decorator — default delegation for both methods
class DataSourceDecorator extends DataSource {
  constructor(wrappee) {
    super();
    this._wrappee = wrappee;
  }
  write(data) { return this._wrappee.write(data); }  // default: pure delegation
  read()      { return this._wrappee.read(); }        // default: pure delegation
}

// Concrete Decorator A — Compression (simulated)
class CompressionDecorator extends DataSourceDecorator {
  write(data) {
    const compressed = `COMPRESSED(${JSON.stringify(data)})`;  // simulate
    console.log('[COMPRESS] Compressing before write');
    super.write(compressed);  // CRITICAL: must delegate
  }
  read() {
    const raw = super.read();  // delegate first
    const decompressed = raw ? JSON.parse(raw.slice(11, -1)) : null;  // simulate
    console.log('[COMPRESS] Decompressing after read');
    return decompressed;
  }
}

// Concrete Decorator B — Encryption (simulated)
class EncryptionDecorator extends DataSourceDecorator {
  write(data) {
    const encrypted = Buffer.from(String(data)).toString('base64');  // simulate
    console.log('[ENCRYPT] Encrypting before write');
    super.write(encrypted);
  }
  read() {
    const raw = super.read();  // delegate first
    const decrypted = raw ? Buffer.from(raw, 'base64').toString() : null;
    console.log('[ENCRYPT] Decrypting after read');
    return decrypted;
  }
}

// Stack: Encryption wraps Compression wraps File
// Write order:  Encrypt → Compress → File
// Read order:   File → Decompress → Decrypt
const source = new EncryptionDecorator(
  new CompressionDecorator(
    new FileDataSource('data.bin')
  )
);

const payload = { user: 'Alice', secret: 'project-alpha' };
source.write(payload);
// [ENCRYPT] Encrypting before write
// [COMPRESS] Compressing before write
// [FILE] Writing to data.bin: Q09N...

const recovered = source.read();
// [FILE] Reading from data.bin
// [COMPRESS] Decompressing after read
// [ENCRYPT] Decrypting after read
console.log(recovered); // { user: 'Alice', secret: 'project-alpha' }

